import{_ as e,o as t,c as n,aj as o}from"./framework.js";const l=JSON.parse('{"title":"Organizations | Manual | Admin CMS","description":"Every Kooboo account has its own organization; the account owner is the organization administrator. Admins can add members. After a member switches into an organization, they can manage…","frontmatter":{"title":"Organizations | Manual | Admin CMS","description":"Every Kooboo account has its own organization; the account owner is the organization administrator. Admins can add members. After a member switches into an organization, they can manage…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/manual/org.html"}]]},"headers":[],"relativePath":"cms/manual/org.md","filePath":"en/cms/manual/org.md","lastUpdated":1793030278000}'),i={name:"cms/manual/org.md"};function r(s,a,c,h,m,d){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="organizations" tabindex="-1">Organizations <a class="header-anchor" href="#organizations" aria-label="Permalink to &quot;Organizations&quot;">​</a></h1><p>Every Kooboo account has its own organization; the account owner is the organization administrator. Admins can add members. After a member switches into an organization, they can manage sites they have permission for in that organization.</p><h2 id="add-a-member" tabindex="-1">Add a member <a class="header-anchor" href="#add-a-member" aria-label="Permalink to &quot;Add a member&quot;">​</a></h2><p>Two ways in:</p><ul><li>Click your username at the top right, then the second item in the menu (the current organization name).</li><li>On the account home page, open <strong>Account settings → Organization → More</strong>.</li></ul><p>Enter the person’s Kooboo <strong>username</strong> to add them to this organization.</p><h2 id="switch-organization" tabindex="-1">Switch organization <a class="header-anchor" href="#switch-organization" aria-label="Permalink to &quot;Switch organization&quot;">​</a></h2><p>On the account home page, open <strong>Account settings → Organization</strong>, check the organization to enter, then click <strong>Switch organization</strong>. You are signed out; after you sign in again you are in that organization and can work on sites you have access to there, or create sites under it.</p><h2 id="add-a-member-as-a-site-user" tabindex="-1">Add a member as a site user <a class="header-anchor" href="#add-a-member-as-a-site-user" aria-label="Permalink to &quot;Add a member as a site user&quot;">​</a></h2><p>After someone joins the organization, they usually still need a site-level role before they can open a given site.</p><p>Open <strong>Site settings → Site Users</strong>, click <strong>Add user</strong>, then choose the user and role. They get the site permissions of that role.</p>',11)])])}const u=e(i,[["render",r]]);export{l as __pageData,u as default};
